/bin/bash -lc "python - <<'PY'
import os, urllib.request, socket
print('Key configured:', bool(os.getenv('ASSEMBLYAI_API_KEY')))
print('Proxy variables:', {k:v for k,v in os.environ.items() if k.lower() in ('http_proxy','https_proxy','all_proxy','no_proxy')})
for host in ['api.assemblyai.com','www.assemblyai.com','raw.githubusercontent.com']:
 print(host, socket.gethostbyname_ex(host))
for url in ['https://api.assemblyai.com/v2/transcript','https://www.assemblyai.com/docs','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/types.py']:
 try:
  r=urllib.request.urlopen(url, timeout=20)
  s=r.read().decode()
  print(url,r.status,s[:1000]);
  if 'types.py' in url: open('/tmp/assembly-types.py','w').write(s)
 except Exception as e: print(url,type(e).__name__,str(e))
PY"

